# ---------------- languages ----------------
# Every page is built in three languages with the same file names: Russian at site/, Kazakh at site/kz/, German at
# site/de/. Interface and home-page texts sit side by side as t('по-русски', 'auf Deutsch'); the Kazakh ones are in
# build/texts_kk.py (KK, keyed by the Russian text, and P_KK for the projects); the German texts of the projects are in P_DE.
# d is the prefix from a page to site/ (assets, the other languages), root(d) the prefix to its own language's root.
from texts_kk import KK, P_KK
LANGS = ('ru', 'kk', 'de')
DIR = {'ru': '', 'kk': 'kz/', 'de': 'de/'}                 # folder of each language inside site/
SWITCH = [('kk', 'KZ', 'Қазақша'), ('ru', 'RU', 'Русский'), ('de', 'DE', 'Deutsch')]   # the RU | KZ | DE switch, in its order
LOCALE = {'ru': 'ru_RU', 'kk': 'kk_KZ', 'de': 'de_DE'}
OG = {'ru': 'og.jpg', 'kk': 'og-kz.jpg', 'de': 'og-de.jpg'}
L = 'ru'
def t(ru, de):
    if L == 'de': return de
    if L == 'kk':
        if (ru, de) in KK: return KK[(ru, de)]      # the same Russian text translated differently where the German differs
        if ru not in KK: raise KeyError('no Kazakh text for: ' + ru)
        return KK[ru]
    return ru
def up(): return '' if L == 'ru' else '../'             # from a language root up to site/
def root(d): return d[3:] if L != 'ru' else d

