def pv(p, k):
    """a project's field in the language being built (German from P_DE, Kazakh from P_KK, everything else shared)"""
    if L in ('de', 'kk'):
        tr = (P_DE if L == 'de' else P_KK)[p['slug']]
        if k == 'docs':
            return [(tt, ext, url, sub) for (tt, sub), (_, ext, url, _) in zip(tr['docs'], p['docs'])]
        if k in tr: return tr[k]
    return p.get(k)

