def lang_switch(d, rel):
    """KZ | RU | DE: links to the same page in each language (rel: the page's path inside a language root)"""
    out = ''
    for code, label, name in SWITCH:
        cur = ' aria-current="true"' if code == L else ''
        out += f'<a href="{d}{DIR[code]}{rel}" hreflang="{code}" lang="{code}" aria-label="{name}"{cur}>{label}</a>'
    return f'<div class="lang" role="group" aria-label="{t("Язык сайта", "Sprache")}">{out}</div>'

